class JoinExporter:
    def __init__(self, separator): self.separator = separator
    def export(self, rows): return self.separator.join(rows)
class ReportService:
    def __init__(self, exporter): self.exporter = exporter
    def build(self, rows): return self.exporter.export(rows)
def solve(data): return ReportService(JoinExporter(data['separator'])).build(data['rows'])
